CREATE TABLE public.sms_subscribers (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, email TEXT NOT NULL, phone TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'homepage_popup', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), UNIQUE (email, phone)); GRANT INSERT ON public.sms_subscribers TO anon, authenticated; GRANT ALL ON public.sms_subscribers TO service_role; ALTER TABLE public.sms_subscribers ENABLE ROW LEVEL SECURITY; CREATE POLICY "Anyone can sign up for texts" ON public.sms_subscribers FOR INSERT TO anon, authenticated WITH CHECK (true);